30	#[test]
31	fn clifftop_retreat_enters_tapped_without_matching_land() {
32	    let reg = registry();
33	    let mut state = game_at_step(Step::PrecombatMain, P0);
34	
35	    // Play Clifftop Retreat with no Mountains or Plains.
36	    let retreat = spell_in_hand(&mut state, &reg, "Clifftop Retreat", P0);
37	    state.get_player_mut(P0).land_plays_remaining = 1;
38	
39	    let legal = engine::legal_actions(&state, &reg);
40	    let play = legal.actions.iter().find(|a| matches!(a, Action::PlayLand { object_id } if *object_id == retreat)).unwrap();
41	    state = engine::submit_action(&state, play, &reg);
42	
43	    // Process triggers so on_enter_battlefield fires.
44	    mtg_engine::triggers::collect_triggers(&mut state, &reg);
45	    mtg_engine::triggers::resolve_next_trigger(&mut state, &reg);
46	
47	    assert!(state.get_object(retreat).unwrap().tapped, "Should enter tapped without matching land");
48	}
