213	#[test]
214	fn moorland_haunt_creates_spirit_token() {
215	    let reg = registry();
216	    let mut state = game_at_step(Step::PrecombatMain, P0);
217	
218	    let mh_card_id = reg.get_id_by_name("Moorland Haunt").unwrap();
219	    let mh = state.create_object(mh_card_id, P0, Zone::Battlefield, None, None);
220	    state.get_object_mut(mh).unwrap().name = "Moorland Haunt".into();
221	
222	    // Put a creature in graveyard.
223	    let creature = ready_creature(&mut state, P0, 2, 2);
224	    state.move_object(creature, Zone::Graveyard);
225	
226	    // Give mana.
227	    state.get_player_mut(P0).mana_pool.add(ManaType::White, 1);
228	    state.get_player_mut(P0).mana_pool.add(ManaType::Blue, 1);
229	
230	    let legal = engine::legal_actions(&state, &reg);
231	    let activate = legal.actions.iter().find(|a| matches!(a, Action::ActivateAbility { object_id, .. } if *object_id == mh));
232	    assert!(activate.is_some(), "Should be able to activate Moorland Haunt");
233	
234	    state = engine::submit_action(&state, activate.unwrap(), &reg);
235	
236	    // Check a Spirit token was created.
237	    let spirits: Vec<_> = state.objects.values()
238	        .filter(|o| o.zone == Zone::Battlefield && o.is_token && o.name.contains("Spirit"))
239	        .collect();
240	    assert_eq!(spirits.len(), 1, "Should create one Spirit token");
241	    assert_eq!(spirits[0].power, Some(1));
242	    assert_eq!(spirits[0].toughness, Some(1));
243	    assert!(spirits[0].keywords.contains(&Keyword::Flying));
244	
245	    // The creature should be exiled.
246	    assert_eq!(state.get_object(creature).unwrap().zone, Zone::Exile);
247	}
